//! Tests of Identify's check of the scheduling variable when a start begins (specification 35, C10 Identify, D-21). The tank is the
//! one of `control-studio-gain-schedule.test.ts`, generated by the schedule's own setup as the tests of `loops.rs` generate it.

use serde_json::json;
use trust_control::failure::{Cause, NextAction};
use trust_control::loop_definition::{Action, LoopDefinition, LoopScope, ModeWhenTrue};
use trust_control::setup::catalog::{decode_catalog_answer, CompiledCatalog};
use trust_control::setup::loop_bindings::FormSignal;
use trust_control::setup::pid_loop::{ModeChoice, SignalChoice};
use trust_control::setup::schedule_loop::{
    schedule_loop_definitions, ScheduleLoopDraft, SchedulePointDraft, SchedulingVariableDraft,
};
use trust_control::signals::{loop_inspection_bindings, InspectionSample, Quality};

use super::{scheduling_start, value_in_scan};

fn scope() -> LoopScope {
    LoopScope {
        project_id: "project:identify".to_owned(),
        runtime_id: "runtime-1".to_owned(),
    }
}

/// The tank's compiled program: the level, the setpoint, the valve, the manual output, the mode, the startup flag and the four
/// table gains.
fn tank_catalog() -> CompiledCatalog {
    let answer = json!({
        "ok": true,
        "processImage": {},
        "controlSymbols": {
            "symbols": [
                { "symbol": "P1.LevelM", "type": "LREAL", "address": "%IL0" },
                { "symbol": "P1.SetpointM", "type": "LREAL", "address": "%ML0" },
                { "symbol": "P1.ValvePct", "type": "LREAL", "address": "%QL0" },
                { "symbol": "P1.ManualPct", "type": "LREAL", "address": "%ML8" },
                { "symbol": "P1.Auto", "type": "BOOL" },
                { "symbol": "P1.Started", "type": "BOOL" },
                { "symbol": "P1.KpLow", "type": "LREAL" },
                { "symbol": "P1.KiLow", "type": "LREAL" },
                { "symbol": "P1.KpHigh", "type": "LREAL" },
                { "symbol": "P1.KiHigh", "type": "LREAL" }
            ],
            "controllers": [
                { "instance": "P1", "type": "Main", "tasks": [{ "name": "MainTask", "intervalMs": 100 }] },
                { "instance": "P1.Loop", "type": "Control.PID", "tasks": [{ "name": "MainTask", "intervalMs": 100 }] }
            ],
            "links": [],
            "writes": ["P1.ValvePct"]
        }
    });
    decode_catalog_answer(&answer)
        .expect("the compiled answer decodes")
        .control
}

fn signal(symbol: &str, unit: &str, maximum: f64) -> FormSignal {
    FormSignal {
        symbol: symbol.to_owned(),
        unit: unit.to_owned(),
        minimum: Some(0.0),
        maximum: Some(maximum),
    }
}

fn point(name: &str, value: f64, proportional: &str, integral: &str) -> SchedulePointDraft {
    SchedulePointDraft {
        name: name.to_owned(),
        value: Some(value),
        tolerance: Some(0.01),
        proportional_gain: proportional.to_owned(),
        integral_gain: integral.to_owned(),
    }
}

/// The tank's schedule: Low at 0.09 m and High at 0.49 m, each with a tolerance of 0.01 m.
fn tank_draft() -> ScheduleLoopDraft {
    ScheduleLoopDraft {
        name: "Tank level".to_owned(),
        action: Action::Direct,
        instance: "P1.Loop".to_owned(),
        parameter_record: "P1.Parameters".to_owned(),
        scheduling: SchedulingVariableDraft {
            symbol: "P1.LevelM".to_owned(),
            unit: "m".to_owned(),
        },
        process_variable: signal("P1.LevelM", "m", 2.0),
        manipulated_variable: signal("P1.ValvePct", "%", 100.0),
        setpoint: SignalChoice {
            symbol: "P1.SetpointM".to_owned(),
            unit: None,
            minimum: None,
            maximum: None,
        },
        mode: ModeChoice {
            symbol: "P1.Auto".to_owned(),
            when_true: ModeWhenTrue::Auto,
        },
        manual_output: "P1.ManualPct".to_owned(),
        points: vec![
            point("Low", 0.09, "P1.KpLow", "P1.KiLow"),
            point("High", 0.49, "P1.KpHigh", "P1.KiHigh"),
        ],
        experiment_step: None,
        experiment_duration_seconds: None,
        startup_flag: Some("P1.Started".to_owned()),
    }
}

/// The loop that tunes the first point of the draft's table (Low, for the tank).
fn low_loop(draft: &ScheduleLoopDraft) -> LoopDefinition {
    schedule_loop_definitions(&tank_catalog(), &scope(), draft)
        .expect("the tank's schedule")
        .remove(0)
}

/// The same loop with its schedule removed: a loop without a schedule.
fn plain_loop(loop_definition: &LoopDefinition) -> LoopDefinition {
    let mut plain = loop_definition.clone();
    plain
        .controller
        .project
        .as_mut()
        .expect("the tank's law")
        .schedule = None;
    plain
}

#[test]
fn a_value_within_the_tolerance_of_the_own_point_is_kept_for_the_identification() {
    assert_eq!(
        scheduling_start(&low_loop(&tank_draft()), Some(0.095)),
        Ok(Some(0.095))
    );
}

#[test]
fn a_value_outside_the_tolerance_of_the_own_point_refuses_the_start() {
    let refusal = scheduling_start(&low_loop(&tank_draft()), Some(0.11)).expect_err("refused");
    assert!(
        refusal.message.contains("outside the tolerance"),
        "{}",
        refusal.message
    );
    assert_eq!(
        (refusal.cause, refusal.next_action),
        (Cause::Settings, NextAction::Identify)
    );
}

#[test]
fn a_start_with_no_value_read_is_refused() {
    let refusal = scheduling_start(&low_loop(&tank_draft()), None).expect_err("refused");
    assert_eq!(
        refusal.message,
        "The scheduling variable cannot be read, so Identify cannot check the operating point."
    );
    assert_eq!(
        (refusal.cause, refusal.next_action),
        (Cause::Runtime, NextAction::ConnectRuntime)
    );
}

#[test]
fn a_loop_without_a_schedule_has_no_operating_point_to_check() {
    let plain = plain_loop(&low_loop(&tank_draft()));
    assert_eq!(scheduling_start(&plain, None), Ok(None));
    assert_eq!(scheduling_start(&plain, Some(7.0)), Ok(None));
}

#[test]
fn a_difference_equal_to_the_tolerance_is_accepted() {
    // The values are exact in binary, so the difference is exactly the tolerance (D-21).
    let mut draft = tank_draft();
    draft.points[0].value = Some(0.5);
    draft.points[0].tolerance = Some(0.25);
    draft.points[1].value = Some(1.0);
    let low = low_loop(&draft);
    assert_eq!(scheduling_start(&low, Some(0.75)), Ok(Some(0.75)));
    assert!(
        scheduling_start(&low, Some(0.76)).is_err(),
        "above the tolerance"
    );
}

#[test]
fn a_scheduled_loop_reads_its_scheduling_variable_by_its_path() {
    let bindings = loop_inspection_bindings(&low_loop(&tank_draft()));
    assert!(
        bindings
            .iter()
            .any(|binding| binding.symbol.as_deref() == Some("P1.LevelM")
                && binding.iec_type == "LREAL"
                && binding.unit.is_none()),
        "{bindings:?}"
    );
}

#[test]
fn the_scheduling_variable_is_added_after_the_loops_own_signals() {
    let with = loop_inspection_bindings(&low_loop(&tank_draft()));
    let without = loop_inspection_bindings(&plain_loop(&low_loop(&tank_draft())));
    assert_eq!(with.len(), without.len() + 1, "one binding is added");
    assert_eq!(&with[..without.len()], &without[..]);
}

#[test]
fn a_signal_that_already_reads_the_variable_by_its_path_adds_no_binding() {
    let mut low = low_loop(&tank_draft());
    low.signals.process_variable.address = None;
    let bindings = loop_inspection_bindings(&low);
    let by_path = bindings
        .iter()
        .filter(|binding| binding.symbol.as_deref() == Some("P1.LevelM"))
        .count();
    assert_eq!(by_path, 1, "the level is named once: {bindings:?}");
}

#[test]
fn the_scheduling_value_is_read_from_the_scan_of_its_own_loop() {
    let low = low_loop(&tank_draft());
    let bindings = loop_inspection_bindings(&low);
    let scan = |quality: Quality| InspectionSample {
        program_revision: "program:1".to_owned(),
        loop_revision: low.revision.clone(),
        bindings: bindings.clone(),
        scan: 1,
        runtime_time_ns: 1,
        captured_at_ms: 1,
        values: vec![Some(0.095); bindings.len()],
        forced: vec![false; bindings.len()],
        quality: vec![quality; bindings.len()],
    };
    assert_eq!(value_in_scan(&low, Some(&scan(Quality::Good))), Some(0.095));
    assert_eq!(value_in_scan(&low, Some(&scan(Quality::Bad))), None);
    assert_eq!(value_in_scan(&low, None), None);
    assert_eq!(
        value_in_scan(&plain_loop(&low), Some(&scan(Quality::Good))),
        None
    );
}
